
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_bmk_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_bmk", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.079066964806985e-01, -1.045365020983845e-01, -9.981528257826362e-02, -9.330769137372934e-02, -8.458173064074015e-02, -7.342348998985293e-02, -6.027518290893416e-02, -4.679633593295501e-02, -3.583138928131210e-02, -2.900818600624264e-02, -2.178424103419245e-02, -4.962671200714618e-02, -6.821858493684202e-02, -2.785133097888359e-02, -1.225032366832175e-02, -1.325293133616316e-04, 1.422990085380666e-02, 5.580129099039601e-03, 6.056997331304076e-04, 2.387558615009202e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


